def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_moves = [h[1] for h in history]
    my_moves = [h[0] for h in history]
    last_my, last_opp = history[-1]

    opp_d = opp_moves.count('D')
    my_d = my_moves.count('D')

    if opp_d > n * 0.8:
        return 'D'

    recent_opp = opp_moves[-10:]
    recent_opp_d = recent_opp.count('D')

    if recent_opp_d > 0:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    punishments = 0
    total_tests = 0
    for i in range(n - 1):
        if my_moves[i] == 'D':
            total_tests += 1
            if opp_moves[i+1] == 'D':
                punishments += 1

    if punishments > 0:
        return 'C'

    if my_d == 0:
        if n >= 10 and n % 10 == 0:
            return 'D'
        return 'C'
    elif my_d == 1 and total_tests == 0:
        return 'C'
    else:
        if total_tests <= 2:
            interval = 10
        elif total_tests <= 5:
            interval = 5
        elif total_tests <= 10:
            interval = 3
        else:
            interval = 1
        if n % interval == 0:
            return 'D'
        return 'C'
